import Anthropic from "@anthropic-ai/sdk";
import { eq } from "drizzle-orm";

import { db } from "~/db";
import { scenes, type Scene } from "~/db/schema";
import { env } from "~/env";
import { KINDS, kindLabel } from "~/lib/taxonomy";
import type { ModelCategory } from "~/db/schema";

/**
 * Scenes are generated by Fable, not by the classifier's model.
 *
 * The two jobs are nothing alike: segmenting a transcript wants the most
 * literal reading available, and writing a piece of generative art wants the
 * opposite. Keeping the model choice here rather than in a shared constant is
 * deliberate — they should be free to diverge.
 */
export const SCENE_MODEL = "claude-fable-5-1";
export const SCENE_PROMPT_VERSION = "scene-v1";

const SYSTEM = `You write short, beautiful Three.js scenes for a personal life-logging app.

Each scene is an ABSTRACT visual for one kind of activity — sleep, an endurance
run, a client call, background television. It is decoration with meaning, not an
illustration: no text, no icons, no human figures, no literal objects. Think
of a screensaver that feels like the thing.

## The contract

You return the BODY of a function called as fn(THREE, canvas). Inside it:

- THREE is the three.js module namespace. It is already imported. Do NOT write
  import or require — there is no module system available to you.
- canvas is an HTMLCanvasElement already in the page and already sized.
- Build a renderer with new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true }).
- Do NOT call requestAnimationFrame yourself, and do NOT add resize listeners.
  The host drives both.
- Return an object with exactly two methods:
    update(elapsedSeconds, width, height)  — draw one frame. Called ~60x/sec.
    dispose()                              — free geometries, materials, renderer.
- No fetch, no window, no document, no localStorage, no timers. Only THREE,
  the canvas, and Math.

## How to answer

Reply with ONE fenced \`\`\`js block holding the function body and nothing else,
then a single final line:

CAPTION: <under 60 characters, what the viewer is looking at>

No prose before or after. No second code block.

## The look

The app's palette is neutral and amber, on white. Stay in it: warm ambers
(#f59e0b, #fbbf24, #fcd34d), greys, and white. No blues, greens or purples.
The background must be transparent or near-white — this sits on a white card.

Motion is slow and calm. Nothing strobes, nothing jumps, nothing loops visibly
in under ten seconds. The whole scene should read at a glance and reward a
longer look.

Prefer a hundred simple things moving well — points, lines, instanced meshes —
over one complex object. Keep it under about 120 lines.

## Correctness

The code is executed exactly as you return it. A syntax error means a blank
card, so: no optional chaining on THREE members, no top-level await, no
trailing commas in function calls, and every variable declared before use.`;

/**
 * 🚨 Fable does not accept a forced `tool_choice`: the API answers
 * `type "tool" and "any" are not supported for this model`. So the contract is
 * a plain-text one — one fenced block, one CAPTION line — and this parses it.
 * Cheaper than it looks: there is exactly one fence in a well-formed answer,
 * and a malformed one fails loudly here rather than as a blank card.
 */
export function parseSceneReply(
  text: string,
): { ok: true; code: string; caption: string | null } | { ok: false; detail: string } {
  const fence = /```(?:js|javascript)?\s*\n([\s\S]*?)```/.exec(text);
  const code = fence?.[1]?.trim();
  if (!code || code.length < 50) return { ok: false, detail: "no javascript block in reply" };
  if (!/return\s*{/.test(code)) return { ok: false, detail: "scene never returns an api" };
  const caption = /^CAPTION:\s*(.+)$/m.exec(text)?.[1]?.trim() ?? null;
  return { ok: true, code, caption };
}

const client = new Anthropic({ apiKey: env.ANTHROPIC_API_KEY });

export type SceneResult =
  | { ok: true; scene: Scene; cached: boolean }
  | { ok: false; detail: string };

/**
 * The brief for a taxonomy slug, built from the criteria the classifier already
 * uses. The scene and the label therefore describe the same thing by
 * construction, instead of drifting the first time a kind is renamed.
 */
export function briefFor(slug: string): string | null {
  const [category, kind] = slug.split(":");
  if (!category || !kind) return null;
  const terms = KINDS[category as ModelCategory];
  if (!terms) return null;
  const term = terms.find((t) => t.value === kind);
  if (!term) return null;
  return `"${term.label}" (${category}) — ${term.criteria}`;
}

/**
 * Generate once, then never again.
 *
 * `slug` is the cache key and the primary key, so two tabs asking for the same
 * scene at the same moment cost one generation and the loser reads the row.
 */
export async function getOrCreateScene(
  slug: string,
  opts: { brief?: string; force?: boolean } = {},
): Promise<SceneResult> {
  if (!opts.force) {
    const existing = await db.select().from(scenes).where(eq(scenes.slug, slug)).limit(1);
    const row = existing[0];
    if (row) return { ok: true, scene: row, cached: true };
  }

  const brief = opts.brief ?? briefFor(slug);
  if (!brief) return { ok: false, detail: `no brief for "${slug}"` };

  let message: Anthropic.Message;
  try {
    message = await client.messages.create({
      model: SCENE_MODEL,
      max_tokens: 8_192,
      system: SYSTEM,
      messages: [
        {
          role: "user",
          content: `Write the scene for:\n\n${brief}\n\nRemember: abstract, amber and neutral on white, calm.`,
        },
      ],
    });
  } catch (error) {
    return { ok: false, detail: error instanceof Error ? error.message : String(error) };
  }

  if (message.stop_reason === "max_tokens") {
    return { ok: false, detail: "truncated at max_tokens" };
  }
  const text = message.content
    .map((c) => (c.type === "text" ? c.text : ""))
    .join("\n");
  const parsed = parseSceneReply(text);
  if (!parsed.ok) return parsed;

  const [row] = await db
    .insert(scenes)
    .values({
      slug,
      brief,
      code: parsed.code,
      caption: parsed.caption,
      model: SCENE_MODEL,
      promptVersion: SCENE_PROMPT_VERSION,
    })
    .onConflictDoUpdate({
      target: scenes.slug,
      set: { code: parsed.code, caption: parsed.caption },
    })
    .returning();

  if (!row) return { ok: false, detail: "insert returned nothing" };
  return { ok: true, scene: row, cached: false };
}

/** Every slug the taxonomy can produce — what a warm-the-cache pass loops. */
export function allSlugs(): { slug: string; label: string }[] {
  return (Object.keys(KINDS) as ModelCategory[]).flatMap((category) =>
    KINDS[category].map((t) => ({
      slug: `${category}:${t.value}`,
      label: `${category} · ${kindLabel(t.value) ?? t.value}`,
    })),
  );
}
